llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "In patients with myasthenia gravis, the oral bioavailability of pyridostigmine was measured as 7.6%, directly below the 20% threshold and higher than neostigmine's 2%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The closest structural analogue neostigmine, also a quaternary ammonium dimethylcarbamate, had absolute oral bioavailability of only 2.0 ± 0.33% after oral dosing in fasted myasthenic patients, supporting poor absorption for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Rivastigmine, a tertiary-amine carbamate, showed high absolute oral bioavailability (71.7% at 6 mg), but its non-quaternary amine structure makes this high-F evidence much less transferable to the permanently charged pyridinium query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct comparative data place pyridostigmine at 7.6% oral bioavailability, and the closest analogue neostigmine is 1-2%; both are below 20%. The high bioavailability of rivastigmine is explained by its tertiary amine and does not overcome the quaternary-ammonium absorption liability.",
  "evidence_gaps": [
    "Only one direct pyridostigmine bioavailability value (7.6%) was retrieved; no dedicated dose-ranging absolute bioavailability study for the query was provided.",
    "The direct value comes from a comparative report without full methodological details.",
    "Potential formulation and dose effects on pyridostigmine absorption are not captured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

